import json,sys,re
path=sys.argv[1]
out=sys.argv[2]
rows=[]
usage={'in':0,'out':0,'cc':0,'cr':0,'n':0}
first=last=None
ts_list=[]
with open(path) as f:
    for ln,line in enumerate(f):
        line=line.strip()
        if not line: continue
        try: d=json.loads(line)
        except Exception: continue
        t=d.get('type')
        if t not in ('user','assistant'): continue
        ts=d.get('timestamp')
        if ts: ts_list.append(ts)
        m=d.get('message',{}) or {}
        c=m.get('content')
        u=m.get('usage') or {}
        if t=='assistant' and u:
            usage['in']+=u.get('input_tokens',0); usage['out']+=u.get('output_tokens',0)
            usage['cc']+=u.get('cache_creation_input_tokens',0); usage['cr']+=u.get('cache_read_input_tokens',0); usage['n']+=1
        blocks=[]
        if isinstance(c,str):
            blocks=[('text',c)]
        elif isinstance(c,list):
            for b in c:
                if not isinstance(b,dict): continue
                bt=b.get('type')
                if bt=='text': blocks.append(('text',b.get('text','')))
                elif bt=='tool_use':
                    blocks.append(('tool',b.get('name',''),b.get('input',{})))
                elif bt=='tool_result':
                    cc=b.get('content')
                    if isinstance(cc,list):
                        s=' '.join(x.get('text','') for x in cc if isinstance(x,dict))
                    else: s=str(cc)
                    blocks.append(('result',s))
        for b in blocks:
            if b[0]=='text':
                txt=b[1].strip()
                if txt: rows.append((ln,ts,t,'TEXT',txt))
            elif b[0]=='tool':
                name=b[1]; inp=b[2]
                if name=='Bash': s=str(inp.get('command',''))[:600]
                elif name in ('Read','NotebookRead'): s=str(inp.get('file_path',''))
                elif name in ('Write',): s=str(inp.get('file_path',''))+' <<'+str(len(str(inp.get('content',''))))+'B>>'
                elif name=='Edit': s=str(inp.get('file_path',''))
                elif name in ('Agent','Task'): s='MODEL='+str(inp.get('model'))+' DESC='+str(inp.get('description',''))+' PROMPT:'+str(inp.get('prompt',''))[:4000]
                else: s=json.dumps(inp)[:500]
                rows.append((ln,ts,t,'TOOL:'+name,s))
            else:
                rows.append((ln,ts,t,'RESULT',b[1][:300]))
with open(out,'w') as g:
    for r in rows:
        g.write('%d\t%s\t%s\t%s\t%s\n'%(r[0],r[1],r[2],r[3],r[4].replace('\n','\\n')))
print('lines',len(rows))
print('usage',usage)
print('total context', usage['in']+usage['cc']+usage['cr'])
print('first ts',min(ts_list) if ts_list else None,'last ts',max(ts_list) if ts_list else None)
EOF
